  secondary_keywords = (select array_agg(distinct k) from unnest(secondary_keywords || array['small business website maintenance','website maintenance for small business','small business website maintenance cost','website maintenance package pricing']) k),
  schema_markup = case when schema_markup ? 'name' then jsonb_set(jsonb_set(schema_markup, '{name}', to_jsonb('Small Business Website Maintenance Cost & Packages'::text)), '{description}', to_jsonb('What small business website maintenance really costs per year: domain, hosting, updates and packages compared, plus a checklist and signs you''re overpaying.'::text)) else schema_markup end,
  updated_at = now(),
  title = 'Small Business Website Maintenance Cost: What You Should Really Pay'
where slug = 'website-maintenance-cost' returning slug, reading_time_minutes;
